export function getClusterDescription(clusterId: string): ClusterDescription {
  return CLUSTER_DESCRIPTIONS[clusterId] ?? FALLBACK
}

/** First ~N words for preview, preserving readable truncation. */
export function previewWords(text: string, count = 28): { preview: string; hasMore: boolean } {
  const words = text.trim().split(/\s+/)
  if (words.length <= count) return { preview: text.trim(), hasMore: false }
  return { preview: `${words.slice(0, count).join(' ')}…`, hasMore: true }
}
